mapper.select:
SELECT o.payment_type AS paymentType, SUM(CASE WHEN o.order_type = 'NORMAL' THEN od.unit_price * od.quantity WHEN o.order_type = 'REFUND' THEN -(od.unit_price * od.quantity) ELSE od.unit_price * od.quantity END) AS paymentAmount FROM order_details od LEFT JOIN orders o ON od.order_id = o.id WHERE 1=1
AND o.pay_time >= #{params.start}
AND o.pay_time <= #{params.end}
AND o.lead_month like concat('%', #{params.leadMonth}, '%')
AND EXISTS ( SELECT 1 FROM customer_info ci WHERE ci.id = o.customer_id AND COALESCE(NULLIF(ci.owner_user_name, ''), ci.create_by_name) like concat('%', #{params.salesPerson}, '%') )
and od.unit_price * od.quantity = #{params.amount}
AND od.order_detail_type = #{params.orderDetailType}
AND EXISTS ( SELECT 1 FROM sys_user su JOIN sys_user_department sud ON su.id = sud.user_id AND sud.deleted = 0 JOIN customer_info ci2 ON COALESCE(NULLIF(ci2.owner_user, ''), ci2.create_by) = su.username WHERE ci2.id = o.customer_id AND sud.department_id = #{params.deptId} )
AND NOT EXISTS ( SELECT 1 FROM sys_user su JOIN sys_user_department sud ON su.id = sud.user_id AND sud.deleted = 0 JOIN customer_info ci2 ON COALESCE(NULLIF(ci2.owner_user, ''), ci2.create_by) = su.username WHERE ci2.id = o.customer_id AND sud.department_id IN
#{item}
)
AND EXISTS ( SELECT 1 FROM sys_business_product sbp JOIN sys_business sb ON sb.id = sbp.business_id AND sb.deleted = 0 WHERE sbp.product_id = od.product_id AND sbp.deleted = 0 AND sb.business_name LIKE CONCAT('%', #{params.businessNameContains}, '%') )
AND NOT EXISTS ( SELECT 1 FROM sys_business_product sbp JOIN sys_business sb ON sb.id = sbp.business_id AND sb.deleted = 0 WHERE sbp.product_id = od.product_id AND sbp.deleted = 0 AND sb.business_name LIKE CONCAT('%', #{params.excludeBusinessNameContains}, '%') )
GROUP BY o.payment_type ORDER BY o.payment_type DESC

SELECT ci.id AS customerId, ci.customer_name AS customerName, CASE WHEN o.order_type = 'NORMAL' THEN od.unit_price * od.quantity WHEN o.order_type = 'REFUND' THEN -(od.unit_price * od.quantity) ELSE od.unit_price * od.quantity END AS amount, od.product_id AS productId, od.product_name AS productName, o.pay_time AS payTime, o.payment_type AS paymentType, o.lead_month AS leadMonth, IFNULL(ci.owner_user_name, ci.create_by_name) as salesPerson, od.order_detail_type AS orderDetailType FROM order_details od LEFT JOIN orders o ON od.order_id = o.id LEFT JOIN customer_info ci ON o.customer_id = ci.id WHERE 1=1
AND o.pay_time >= #{params.start}
AND o.pay_time <= #{params.end}
AND o.payment_type = #{params.paymentType}
AND o.lead_month like concat('%', #{params.leadMonth}, '%')
AND COALESCE(NULLIF(ci.owner_user_name, ''), ci.create_by_name) like concat('%', #{params.salesPerson}, '%')
and od.unit_price * od.quantity = #{params.amount}
AND od.order_detail_type = #{params.orderDetailType}
AND EXISTS ( SELECT 1 FROM sys_user su JOIN sys_user_department sud ON su.id = sud.user_id AND sud.deleted = 0 WHERE COALESCE(NULLIF(ci.owner_user, ''), ci.create_by) = su.username AND sud.department_id = #{params.deptId} )
AND NOT EXISTS ( SELECT 1 FROM sys_user su JOIN sys_user_department sud ON su.id = sud.user_id AND sud.deleted = 0 WHERE COALESCE(NULLIF(ci.owner_user, ''), ci.create_by) = su.username AND sud.department_id IN
#{item}
)
AND EXISTS ( SELECT 1 FROM sys_business_product sbp JOIN sys_business sb ON sb.id = sbp.business_id AND sb.deleted = 0 WHERE sbp.product_id = od.product_id AND sbp.deleted = 0 AND sb.business_name LIKE CONCAT('%', #{params.businessNameContains}, '%') )
AND NOT EXISTS ( SELECT 1 FROM sys_business_product sbp JOIN sys_business sb ON sb.id = sbp.business_id AND sb.deleted = 0 WHERE sbp.product_id = od.product_id AND sbp.deleted = 0 AND sb.business_name LIKE CONCAT('%', #{params.excludeBusinessNameContains}, '%') )
ORDER BY o.pay_time DESC
